+            let block_names = block_dls |> List.concat_map(line_exp_names);
+            let colliding =
+              line_exp_names(dl)
+              |> List.filter(x => List.mem(x, block_names));
+            switch (dl) {
+            | LetLine(xp, _) => pat_binder_ids(colliding, xp)
+            | TypeLine(_) => []
