+                    ...x,
+                    term: Tuple(List.map(component, xs)),
+                  }
+                | ListLit(xs) => {
+                    ...x,
+                    term: ListLit(List.map(component, xs)),
+                  }
+                | TupLabel(l, inner) => {
+                    ...x,
+                    term: TupLabel(l, component(inner)),
+                  }
