+let extended_ap_pat = (p: Pat.t, name: string): option((Pat.t, Id.t)) => {
+  let newvar = {
+    ...fresh_pat(Var(name)),
+    annotation: {
+      ...IdTagged.IdTag.mk_internal([Id.mk()]),
