+    switch (ap_of(e)) {
+    | Some(fid) => Some(fid)
+    | None =>
+      switch (find_path(~hit=hit_node(target), program)) {
+      | Some(path) when List.length(path) >= 2 =>
+        ap_of(List.nth(path, List.length(path) - 2))
+      | _ => None
+      }
+    };
+  | None => None
+  };
