+  let default: t = {
+    nodes: [],
+    edges: [],
+    attachments: [],
+    col_gap: 110.,
+    row_gap: 56.,
+    margin: 70.,
+    x_stretch: 1.,
+    y_stretch: 1.,
+    order_sweeps: 4,
+    order_hysteresis: 0.6,
