+  let cl = Js.Unsafe.get(el, "classList");
+  List.iter(
+    c =>
+      ignore(
+        Js.Unsafe.meth_call(
+          cl,
+          "remove",
+          [|Js.Unsafe.inject(Js.string(c))|],
+        ),
+      ),
+    ["mode-speech", "mode-thought", "mode-hidden"],
+  );
+  ignore(
+    Js.Unsafe.meth_call(
+      cl,
+      "add",
+      [|Js.Unsafe.inject(Js.string(mode_class(m)))|],
+    ),
+  );
+};
