+    | Speech =>
+      switch (el_by_class("say-text")) {
+      | Some(t) => set_text(t, say_text^)
+      | None => ()
+      }
+    | Thought =>
+      switch (el_by_class("bubble-text")) {
+      | Some(el) =>
+        let w = clean_cut(advance());
+        set_text(el, w);
+        /* a fade on each replacement, so the change reads as motion */
