+              pt((tx, ty)),
+              pt((cx +. ox *. on, cy +. oy *. on)),
+            );
+          } else {
+            Printf.sprintf(
+              "L %s Q %s %s",
+              pt((cx -. ix *. r, cy -. iy *. r)),
+              pt((cx, cy)),
+              pt((cx +. ox *. r, cy +. oy *. r)),
+            );
+          },
+        corners,
+      ),
+    );
