+  switch (CanvasAvatar.body()) {
+  | None => ()
+  | Some(b) =>
+    switch (child(b, ".canvas-avatar-bubble")) {
+    | None => ()
+    | Some(bub) when mode() != Hidden =>
+      let m = mode();
+      let (cx, cy, r) = CanvasAvatar.bounding_circle();
