+    Js.Unsafe.set(
+      g,
+      "__canvasStage",
+      Js.Unsafe.callback(() => CanvasBuffer.stage_beat(~lead=true, ())),
+    );
+    /* __canvasBurst() marks an agent action so the next edit is paced
