+        | [] =>
+          let (v_key, v_kind) =
+            if (is_mod) {
+              ("{}" ++ "@" ++ qn, Product);
+            } else if (path != []) {
+              (
+                /* member constants orbit their module's former node: the
+                   hull contains them regardless of their value's type */
+                "{}" ++ "@" ++ String.concat(".", path),
+                Product,
+              );
