+              ensure_grid(~hole_path=path, ret_key, ret_kind);
+              ensure_sat(
+                ~m_path=path,
+                ~anchor_key=ret_key,
+                ~output=false,
+                ~dup=qn,
+                k,
+              );
+            | [(k, kind)] =>
+              ensure_grid(~hole_path=path, k, kind);
+              k;
+            | comps =>
+              let product_key =
+                "("
+                ++ String.concat(
+                     ", ",
+                     List.map(((k, _)) => display_label(k), comps),
+                   )
+                ++ ")";
+              let part_keys =
+                List.mapi(
+                  (ci, (k, kind)) =>
+                    switch (kind) {
+                    | Builtin =>
+                      /* per-component dup: (Int, Int) must yield TWO
+                         Int terminals, not a deduped one */
+                      ensure_sat(
+                        ~m_path=path,
+                        ~anchor_key=product_key,
+                        ~output=false,
+                        ~dup=product_key ++ "c" ++ string_of_int(ci),
+                        k,
+                      )
+                    | _ =>
+                      ensure_grid(~hole_path=path, k, kind);
+                      k;
+                    },
+                  comps,
+                );
+              ensure(
+                mk_node(
+                  ~kind=Product,
+                  ~label="()",
+                  ~parts=part_keys,
+                  ~deps=
+                    List.filter_map(
+                      ((k, kind)) =>
+                        switch (kind) {
+                        | Builtin => None
+                        | _ => Some(k)
+                        },
+                      comps,
+                    ),
+                  product_key,
+                ),
+              );
+              product_key;
+            };
+          /* result node: builtin results dock to the input node */
+          let dst_key =
+            switch (ret_kind) {
+            | Builtin =>
+              ensure_sat(
+                ~m_path=path,
+                ~anchor_key=input_key,
+                ~output=true,
+                ~dup=qn,
+                ret_key,
+              )
+            | _ =>
+              ensure_grid(~hole_path=path, ret_key, ret_kind);
+              ret_key;
+            };
+          (
+            es
+            @ [
+              {
+                e_name: qn,
+                e_label: name,
+                m_path: path,
+                e_id: id,
+                e_ty: pretty_ty(ty),
+                e_src: input_key,
+                dst: dst_key,
+                e_doc: doc,
+                e_err: err,
+                e_hole: hole,
+                main: path == [] && use_count(name) >= 2,
+                tests: [],
+                e_arg_ids: arg_ids,
+                e_whole_ids: whole_ids,
+                e_out_id: out_id,
+                e_deps:
+                  dvars
+                  |> List.filter(v => v != name && List.mem(v, binding_names)),
+              },
+            ],
+            vs,
+          );
+        };
+      },
+      ([], []),
+      List.combine(bindings, qns),
+    );
+
+  /* Tests: attach to their lexical subject (see test_subject). */
+  let edge_names = List.map(e => e.e_name, edges_raw);
+  let status_of = (id: Id.t): option(TestStatus.t) =>
+    switch (test_results) {
+    | Some(tr) =>
+      TestMap.lookup(id, tr.test_map) |> Option.map(TestMap.joint_status)
+    | None => None
+    };
+  let (edge_tests, loose_tests, all_tests) =
+    List.fold_left(
+      ((et, lt, all), (_, item)) =>
+        switch (item) {
+        | ITest(term, body) =>
+          let t_id = Exp.rep_id(term);
+          let vars = exp_refs(body);
+          /* a mention matches an edge by its qualified name or its bare
+             label (module members are referenced either way) */
+          let t_refs =
+            List.filter(
+              name => {
+                let bare =
+                  switch (List.rev(String.split_on_char('.', name))) {
+                  | [b, ..._] => b
+                  | [] => name
+                  };
+                List.mem(name, vars) || List.mem(bare, vars);
+              },
+              edge_names,
+            );
+          let info = {
+            t_id,
+            status: status_of(t_id),
+            t_body: body,
+            t_refs,
+          };
+          switch (test_subject(~edge_names, body)) {
+          | Some(target) => ([(target, info), ...et], lt, all @ [info])
+          | None => (et, lt @ [info], all @ [info])
+          };
+        | _ => (et, lt, all)
+        },
+      ([], [], []),
+      items,
+    );
+  let edges =
+    List.map(
+      e =>
+        {
+          ...e,
+          tests:
+            edge_tests
+            |> List.filter(((name, _)) => name == e.e_name)
+            |> List.rev_map(snd),
+        },
+      edges_raw,
+    );
+
+  let last_def =
+    List.fold_left(
+      (acc, (path, item)) =>
+        path != []
+          ? acc
+          : (
+            switch (item) {
+            | IAlias(Some(id), _, tpat, _) =>
+              switch (tpat.term) {
+              | Var(n) => Some((n, id))
+              | _ => acc
+              }
+            | ILet(Some(id), _, pat, _) =>
+              switch (pat_names(pat)) {
+              | [n, ..._] => Some((n, id))
+              | [] => acc
+              }
+            | _ => acc
+            }
+          ),
+      None,
+      items,
+    );
+  let alias_nodes =
+    List.map(
+      (n: tynode) => {
+        let n =
+          Hashtbl.mem(expanded_aliases, n.key)
+            ? {
+              ...n,
+              hidden_deps: n.deps,
+            }
+            : n;
+        switch (Hashtbl.find_opt(alias_former, n.key)) {
+        | Some((glyph, parts)) => {
+            ...n,
+            former: Some(glyph),
+            parts,
+          }
+        | None => n
+        };
+      },
+      alias_nodes,
+    );
+  {
+    nodes: uniquify_keys(alias_nodes @ extras^),
+    edges,
+    values,
+    loose_tests,
+    all_tests,
+    last_def,
+  };
+};
+
+let extract =
+    (~test_results: option(TestResults.t)=?, statics: CachedStatics.t): t =>
+  Util.PerfTimer.time("canvas-extract", () =>
+    extract_impl(~test_results?, statics)
+  );

