+/* Constellation canvas panel (see plans/agent-canvas.md) */
+
+#canvas-sidebar {
+  display: flex;
+  flex-direction: column;
+  height: 100%;
+  overflow: hidden;
+  font-family: var(--code-font, monospace);
+}
+
+/* main-area split: editor left, canvas right, agent chat free in the sidebar */
+
+/* Absolutely-positioned panes rather than flex items: as flex (or grid)
+   children of #main the panes' cross-size stuck at the line's content
+   height (~half the pane) instead of stretching to the grid-stretched
+   container — absolute insets size directly off #main's box. */
+
+#main.has-canvas-split {
+  position: relative;
+  overflow: hidden;
+}
+
+.main-split-editors {
+  position: absolute;
+  top: 0;
+  bottom: 0;
+  left: 0;
+  right: 44%;
+  overflow: auto;
+  display: flex;
+  flex-direction: column;
+}
+
+#canvas-main {
+  position: absolute;
+  top: 0;
+  bottom: 0;
+  right: 0;
+  width: 44%;
+  min-width: 320px;
+  border-left: 0.6px solid var(--BR2, #ccc);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+}
+
+#canvas-divider {
+  position: absolute;
+  top: 0;
+  bottom: 0;
+  width: 8px;
+  cursor: col-resize;
+  z-index: 6;
+}
+
+#canvas-divider:hover {
+  background: rgba(120, 160, 90, 0.25);
+}
+
+.canvas-split-btn {
+  font-size: 10px;
+  border: 1px solid var(--BR1, #d8c9a3);
+  border-radius: 4px;
+  padding: 1px 8px;
+  cursor: pointer;
+  white-space: nowrap;
+  user-select: none;
+}
+
+.canvas-split-btn:hover {
+  background: var(--Y0, #f6efd8);
+}
+
+.canvas-split-note {
+  padding: 1em;
+  font-size: 12px;
+  display: flex;
+  flex-direction: column;
+  gap: 8px;
+  align-items: flex-start;
+  opacity: 0.85;
+}
+
+.canvas-header {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 10px;
+  padding: 0.4em 0.8em;
+  border-bottom: 0.6px solid var(--BR2, #ccc);
+  flex: 0 0 auto;
+}
+
+/* same typeface parameters as the Probearium title */
+.canvas-title {
+  font-weight: bold;
+  font-size: 1em;
+  text-transform: uppercase;
+  color: var(--ui-header-text, #6b5330);
+  font-family: var(--ui-font, sans-serif);
+  white-space: nowrap;
+}
+
+.canvas-scroll {
+  flex: 1 1 auto;
+  overflow: auto;
+  /* free panning: constant slack all around the board (the dot field
+     fades at the board edges, so the slack reads as open void); scroll
+     anchoring on slide entry skips the margin (CanvasSidebar) */
+  /* dot-grid backdrop over the whole panel; pattern starts one cell in
+     from the top-left corner */
+  /* the transparent border insets the root (and its dot field) one
+     grid cell from the panel edges */
+  border: 14px solid transparent;
+  /* reserve scrollbar space ALWAYS: a scrollbar popping in mid-drag
+     changed the pane width, re-centered the frame, and made every
+     node bounce between adjacent grid cells */
+  scrollbar-gutter: stable;
+  /* free panning made the scroll range permanent; scrollbars would be
+     constant chrome on an infinite canvas, so hide them (two-finger
+     swipe / wheel still pans) */
+  scrollbar-width: none;
+}
+
+.canvas-scroll::-webkit-scrollbar {
+  display: none;
+}
+
+.canvas-pan-pad {
+  padding: 392px; /* keep in sync with CanvasSidebar.pan_slack */
+  width: max-content;
+}
+
+/* ---- authoring toolbar ---- */
+
+.canvas-clock {
+  font-family: var(--code-font, monospace);
+  font-size: 9.5px;
+  opacity: 0.65;
+  white-space: nowrap;
+}
+
+/* lives inside the header row, right of the title */
+.canvas-toolbar {
+  flex: 1 1 auto;
+  min-width: 0;
+  display: flex;
+  align-items: center;
+  /* wraps when the pane is narrow (mode hints float over the canvas,
+     so nothing appears here mid-gesture any more); nothing is cut off */
+  flex-wrap: wrap;
+  gap: 4px;
+  font-size: 11px;
+}
+
+/* zero-height row: the hint pill overlays the canvas without
+   affecting layout */
+.canvas-mode-hint-row {
+  flex: 0 0 auto;
+  height: 0;
+  overflow: visible;
+  position: relative;
+  z-index: 6;
+  display: flex;
+  justify-content: center;
+}
+
+.canvas-mode-hint {
+  position: relative;
+  top: 8px;
+  align-self: flex-start;
+  display: flex;
+  align-items: center;
+  gap: 3px;
+  background: var(--Y1, #f0e2b8);
+  color: var(--BR4, #4a3a20);
+  border: 1px solid var(--BR1, #d8c9a3);
+  border-radius: 10px;
+  padding: 2px 12px;
+  font-size: 11px;
+  /* interactive: base-type chips live in the pill */
+  pointer-events: auto;
+  white-space: nowrap;
+  max-width: 90%;
+  overflow: hidden;
+  text-overflow: ellipsis;
+}
+
+.hint-chip {
+  border: 1px solid var(--BR2, #b09a6a);
+  border-radius: 7px;
+  padding: 0 6px;
+  cursor: pointer;
+  background: var(--df-bg, #fdfdf4);
+  color: var(--token-typ, #9457c9);
+}
+
+.hint-chip:hover {
+  background: var(--Y0, #f6efd8);
+}
+
+.toolbar-spacer {
+  flex: 1 1 auto;
+}
+
+/* same family as the probes sidebar's segmented controls */
+.canvas-tool-btn {
+  border: 1px solid var(--BR1, #d8c9a3);
+  border-radius: 4px;
+  padding: 1px 8px;
+  cursor: pointer;
+  white-space: nowrap;
+  user-select: none;
+}
+
+.canvas-tool-btn:hover {
+  background: var(--Y0, #f6efd8);
+}
+
+.canvas-tool-btn.tool-disabled {
+  opacity: 0.4;
+  cursor: default;
+}
+
+.canvas-tool-btn.tool-disabled:hover {
+  background: transparent;
+}
+
+.canvas-tool-btn.tool-active {
+  background: var(--Y1, #f0e2b8);
+  color: var(--BR4, #4a3a20);
+  font-weight: 500;
+}
+
+.tool-hint {
+  font-size: 10px;
+  font-style: italic;
+  opacity: 0.7;
+}
+
+.canvas-root {
+  position: relative;
+  /* browsers that can interpolate zoom smooth the auto-fit hops;
+     others snap (graceful) */
+  transition: zoom 0.35s ease-out;
+}
+
+/* pinch in progress: every step must land instantly or overlapping
+   0.35s zoom animations oscillate (the pinch judder) */
+.canvas-root.no-zoom-anim {
+  transition: none;
+  /* centering is grid-aligned inside the layout (center_within); an
+     auto margin here would break dot-lattice alignment */
+  margin: 0;
+}
+
+/* dot grid on its own layer so it can fade at the edges without
+   masking the graph itself; it zooms and scrolls with the graph.
+   --dot-pitch is set inline on the root and loops across zoom levels.
+   Dots sit at tile centers: with the half-pitch offset their centers
+   land on lattice multiples, where node centers snap. */
+.canvas-dots-holder {
+  position: sticky;
+  top: 0;
+  left: 0;
+  width: 0;
+  height: 0;
+  z-index: 0;
+}
+
+.canvas-dots {
+  position: absolute;
+  top: 0;
+  left: 0;
+  pointer-events: none;
+}
+
+.canvas-pan-pad.placing {
+  cursor: crosshair;
+}
+
+.canvas-edges {
+  position: absolute;
+  left: 0;
+  top: 0;
+  overflow: visible;
+  pointer-events: none;
+}
+
+/* ---- edges ---- */
+
+/* arrows are the editor's expression color (implementations) */
+.canvas-line,
+.canvas-orbit {
+  stroke: var(--token-exp, #555);
+  stroke-width: 1.4;
+  fill: none;
+  opacity: 0.9;
+}
+
+.canvas-line.edge-main,
+.canvas-orbit.edge-main {
+  stroke-width: 2.6;
+}
+
+.canvas-line.edge-input {
+  stroke-width: 1.1;
+  opacity: 0.5;
+}
+
+.canvas-line.edge-hole,
+.canvas-orbit.edge-hole {
+  stroke-dasharray: 0.1 5.6;
+  stroke-linecap: round;
+  opacity: 0.45;
+}
+
+.canvas-line.edge-err,
+.canvas-orbit.edge-err {
+  stroke: var(--ci-status-error-text, #c0392b);
+}
+
+.canvas-arrowhead {
+  fill: var(--token-exp, #555);
+  opacity: 0.95;
+}
+
+.canvas-arrowhead-sm {
+  fill: var(--token-exp, #555);
+  opacity: 0.5;
+}
+
+.canvas-arrowhead-dep {
+  fill: #4a7a4a;
+  opacity: 0.35;
+}
+
+/* ---- nodes: absolutely positioned circles.
+   Anchored via left/top at the node's center and centered with the
+   standalone CSS `translate` property — NOT `transform`, which the WAAPI
+   FLIP animation overrides mid-flight (translate composes with it). ---- */
+
+.canvas-node {
+  position: absolute;
+  translate: -50% -50%;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  border-radius: 50%;
+  /* types wear the code's Typ purple, on the canvas as in the buffer */
+  border: 1.5px solid var(--token-typ, #9457c9);
+  background: var(--df-bg, #fdfdf4);
+  box-sizing: border-box;
+  z-index: 2;
+  overflow: visible;
+}
+
+.canvas-node.clickable {
+  cursor: pointer;
+}
+
+/* ONE selection color for the canvas (types and functions alike), chosen
+   free of the semantic colors: purple = types, slate = implementations,
+   green = passing tests, red = errors, yellow = the agent. The selected
+   type's own outline takes the color (a single ring, no halo). */
+:root {
+  --canvas-select: #2f6fbf;
+}
+.canvas-node.node-focused {
+  border-color: var(--canvas-select);
+  border-width: 2.5px;
+}
+.canvas-node.kind-product.node-focused {
+  border: 2.5px solid var(--canvas-select);
+}
+.canvas-node.node-focused .canvas-node-label {
+  font-weight: bold;
+  color: var(--canvas-select);
+}
+
+/* placement telegraph: a pulsing seed on the lattice point under the
+   cursor — the node will grow here on click */
+.place-preview.idle {
+  display: none;
+}
+
+.place-preview {
+  position: absolute;
+  translate: -50% -50%;
+  width: 11px;
+  height: 11px;
+  border-radius: 50%;
+  background: var(--token-typ, #9457c9);
+  pointer-events: none;
+  z-index: 4;
+  animation: place-pulse 1.1s ease-in-out infinite;
+}
+
+@keyframes place-pulse {
+  0%,
+  100% {
+    scale: 1;
+    opacity: 0.75;
+  }
+  50% {
+    scale: 1.45;
+    opacity: 1;
+  }
+}
+
+/* a just-placed node grows out of the seed */
+.canvas-node.just-placed {
+  animation: node-grow 0.45s cubic-bezier(0.34, 1.4, 0.64, 1);
+}
+
+/* the actor just changed this element (a hole filled, a type grown, an
+   error fixed): a short glow so the swap reads as the actor's doing */
+.canvas-node.just-changed,
+.canvas-edge-label.just-changed,
+.canvas-value.just-changed {
+  animation: cnv-change-pulse 0.9s ease-out;
+}
+@keyframes cnv-change-pulse {
+  0% {
+    filter: brightness(1) drop-shadow(0 0 0 rgba(120, 90, 200, 0));
+  }
+  25% {
+    filter: brightness(1.25) drop-shadow(0 0 8px rgba(120, 90, 200, 0.8));
+  }
+  100% {
+    filter: brightness(1) drop-shadow(0 0 0 rgba(120, 90, 200, 0));
+  }
+}
+
+@keyframes node-grow {
+  from {
+    scale: 0.18;
+  }
+  to {
+    scale: 1;
+  }
+}
+
+/* connect telegraph: rubber-band lines from collected sources to cursor */
+.connect-preview {
+  position: absolute;
+  left: 0;
+  top: 0;
+  overflow: visible;
+  pointer-events: none;
+  z-index: 4;
+}
+
+.connect-form {
+  stroke: var(--BLACK, #333);
+  stroke-width: 1.2;
+  stroke-dasharray: 0.1 4;
+  stroke-linecap: round;
+  fill: none;
+  opacity: 0.5;
+}
+
+.connect-main {
+  stroke: var(--BLACK, #333);
+  stroke-width: 1.6;
+  fill: none;
+  opacity: 0.55;
+}
+
+.canvas-node.clickable:hover {
+  box-shadow: 0 0 0 3px rgba(120, 160, 90, 0.35);
+}
+
+.canvas-node-label {
+  color: var(--token-typ, #9457c9);
+  font-size: 11px;
+  white-space: nowrap;
+  position: absolute;
+  top: 100%;
+  margin-top: 2px;
+  text-shadow:
+    0 0 3px var(--df-bg, #fdfdf4),
+    0 0 3px var(--df-bg, #fdfdf4);
+}
+
+/* module nodes: type-styled name below, {} glyph centered inside
+   (beats the product-kind centering rule) */
+.canvas-node.canvas-node.node-former .canvas-node-label,
+.canvas-node.canvas-node.node-module .canvas-node-label {
+  position: absolute;
+  top: 100%;
+  left: 50%;
+  bottom: auto;
+  transform: translateX(-50%);
+  margin-top: 2px;
+  font-weight: bold;
+  font-size: 11px;
+  color: var(--token-typ, #9457c9);
+}
+
+.canvas-node.node-module .canvas-node-glyph {
+  position: absolute;
+  inset: 0;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  color: var(--df-bg, #fdfdf4);
+  font-size: 11px;
+  font-family: var(--code-font, monospace);
+  pointer-events: none;
+}
+
+/* folded former badge: an alias whose body IS a tuple/list/sum wears the
+   former's glyph as a small filled disc centered in the node (white on the
+   type purple, like the former nodes it replaces); name sits below */
+.canvas-node.node-former .canvas-node-glyph {
+  position: absolute;
+  inset: 0;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  /* just the glyph, in the type purple — no disc behind it */
+  color: var(--token-typ, #9457c9);
+  font-size: 14px;
+  font-weight: 700;
+  line-height: 1;
+  padding-bottom: 0;
+  font-family: var(--code-font, monospace);
+  pointer-events: none;
+}
+
+.canvas-node.kind-alias {
+  background: color-mix(
+    in srgb,
+    var(--token-typ, #9457c9) 10%,
+    var(--df-bg, #fdfdf4)
+  );
+}
+
+.canvas-node.kind-alias .canvas-node-label {
+  font-weight: bold;
+}
+
+.canvas-node.kind-builtin {
+  border-width: 1px;
+  opacity: 0.55;
+}
+
+/* base types carry their blackboard letter inside (ℤ 𝔹 𝕊 𝔽, or [ℤ]) */
+.canvas-node .canvas-node-glyph.base-glyph {
+  position: absolute;
+  inset: 0;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  color: var(--token-typ, #9457c9);
+  font-family: "STIX Two Math", "Cambria Math", "Latin Modern Math", serif;
+  font-size: 12px;
+  line-height: 1;
+  letter-spacing: -0.5px;
+  /* the math letters' ink sits high in their box: the box is centered
+     (measured 5.0 above / 5.2 below) yet reads high, so lower it 1 px */
+  padding-top: 2px;
+  pointer-events: none;
+}
+.canvas-node.kind-derived .canvas-node-glyph.base-glyph {
+  font-size: 13px;
+}
+.canvas-node.node-glyphed .canvas-node-label {
+  display: none;
+}
+
+.canvas-node.kind-derived {
+  border-style: dotted;
+  opacity: 0.8;
+}
+
+.canvas-node.kind-ghost {
+  border-style: dotted;
+  opacity: 0.5;
+  background: transparent;
+}
+
+.canvas-node.kind-product {
+  border: none;
+  background: var(--token-typ, #9457c9);
+  opacity: 1;
+}
+
+/* former labels ("()" / "[]" / "{}") sit INSIDE the filled node */
+.canvas-node.kind-product .canvas-node-label {
+  color: #fff;
+  top: 0;
+  inset: 0;
+  margin-top: 0;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-weight: normal;
+  font-size: 12px;
+  line-height: 1;
+  /* parentheses: the box centers but the ink reads high — no lift */
+  padding-bottom: 0;
+  letter-spacing: 0.5px;
+  text-shadow: none;
+}
+
+.canvas-formation {
+  stroke: var(--BLACK, #333);
+  stroke-width: 1.2;
+  stroke-dasharray: 0.1 4;
+  stroke-linecap: round;
+  fill: none;
+  opacity: 0.45;
+}
+
+.canvas-leader {
+  stroke: var(--BLACK, #333);
+  stroke-width: 1;
+  stroke-dasharray: 0.1 3.6;
+  stroke-linecap: round;
+  opacity: 0.4;
+}
+
+.canvas-dep {
+  stroke: #4a7a4a;
+  stroke-width: 1;
+  fill: none;
+  opacity: 0.18;
+}
+
+.canvas-node.node-err {
+  border-color: var(--ci-status-error-text, #c0392b);
+  box-shadow: 0 0 6px 1px rgba(192, 57, 43, 0.5);
+}
+
+/* ---- edge labels ---- */
+
