+/* a single outline in the selection color, like the selected type */
+.canvas-edge-label.edge-focused {
+  border-color: var(--canvas-select);
+  border-width: 2px;
+  color: var(--canvas-select);
+}
+
+/* ---- focus strip: one function, flattened input → output ---- */
+
+.canvas-focus {
+  position: relative;
+  flex: 0 0 auto;
+  border-top: 0.6px solid var(--BR2, #ccc);
+  padding: 6px 12px 10px;
+  max-height: 240px;
+  overflow: auto;
+  font-family: var(--code-font, monospace);
+}
+
+.focus-head {
+  display: flex;
+  align-items: baseline;
+  gap: 6px;
+}
+
+.focus-name {
+  font-weight: bold;
+  cursor: pointer;
+  font-size: 13px;
+}
+
+.focus-name:hover {
+  text-decoration: underline;
+}
+
+.focus-ty {
+  font-size: 11px;
+  opacity: 0.65;
+}
+
+/* pinned to the corner with EQUAL top/right insets (it used to ride
+   the header baseline, farther from the right edge than the top) */
+.focus-close {
+  position: absolute;
+  top: 7px;
+  right: 7px;
+  cursor: pointer;
+  color: var(--BR3, #8a744a);
+  padding: 0 2px;
+}
+
+.focus-close:hover {
+  opacity: 1;
+}
+
+.focus-doc {
+  font-size: 11px;
+  font-style: italic;
+  opacity: 0.7;
+  margin: 2px 0 4px;
+}
+
+/* Real probe wells need row width: the flow stacks vertically — input
+   slots, the fn marker, then the output slot — each slot a full-width
+   [chip | probe] row. */
+.focus-flow {
+  display: flex;
+  flex-direction: column;
+  align-items: stretch;
+  gap: 7px;
+  margin-top: 6px;
+  min-width: 0;
+}
+
+.focus-inputs {
+  display: flex;
+  flex-direction: column;
+  gap: 7px;
+  min-width: 0;
+}
+
+.focus-fn {
+  align-self: flex-start;
+  padding-left: 1.5em;
+}
+
+.focus-output {
+  min-width: 0;
+}
+
+.focus-slot {
+  display: flex;
+  align-items: flex-start;
+  gap: 8px;
+  min-width: 0;
+  width: 100%;
+}
+
+.focus-slot .focus-chip {
+  flex: none;
+  margin-top: 2px;
+}
+
+.focus-chip {
+  border: 2px solid var(--token-typ, #9457c9);
+  color: var(--token-typ, #9457c9);
+  border-radius: 999px;
+  padding: 2px 10px;
+  font-size: 11px;
+  background: var(--df-bg, #fdfdf4);
+  cursor: pointer;
+  white-space: nowrap;
+}
+
+.focus-chip.kind-alias {
+  background: color-mix(
+    in srgb,
+    var(--token-typ, #9457c9) 10%,
+    var(--df-bg, #fdfdf4)
+  );
+  font-weight: bold;
+}
+
+.focus-chip.kind-builtin {
+  border-width: 1px;
+  opacity: 0.65;
+}
+
+.focus-chip.kind-ghost {
+  border-style: dotted;
+  opacity: 0.6;
+}
+
+.focus-well {
+  border: 1.5px dotted var(--CREASE, #bbb);
+  border-radius: 5px;
+  padding: 2px 8px;
+  font-size: 10px;
+  opacity: 0.55;
+  min-width: 72px;
+}
+
+.focus-well.well-filled {
+  border-style: solid;
+  opacity: 0.9;
+  display: flex;
+  align-items: baseline;
+  gap: 6px;
+  background: rgba(120, 160, 90, 0.08);
+}
+
+.well-value {
+  white-space: nowrap;
+  border-right: 1px solid var(--CREASE, #ddd);
+  padding-right: 6px;
+}
+
+.well-value:last-of-type {
+  border-right: none;
+  padding-right: 0;
+}
+
+.well-more {
+  opacity: 0.6;
+}
+
+.well-glyph {
+  font-weight: bold;
+}
+
+/* code-rendered chips (type view): inline, sized to content */
+.type-value .code {
+  display: inline-block;
+  position: relative;
+  vertical-align: middle;
+}
+
+/* ---- probe wells: real probe views embedded in the strip ---- */
+
+/* Static-flow overrides for the in-editor probe CSS: the probe's nav-bar
+   is gutter-absolute (left: -1.85em), so reserve that gutter with padding;
+   .projector centers its (absolutely-placed) content in-editor — here the
+   probe flows statically and must top-left align; the drawer (.below
+   slot) stacks below the samples instead of under an editor row. */
+.canvas-probe {
+  position: relative;
+  padding-left: 1.9em;
+  display: flex;
+  flex-direction: column;
+  align-items: flex-start;
+  justify-content: flex-start;
+  gap: 4px;
+  flex: 1 1 auto;
+  min-width: 0;
+}
+
+/* No scroll clipping: probes hang pins/badges slightly outside their box
+   (position:absolute offsets), which under overflow:auto reads as tiny
+   scrollbars. Wrap samples onto extra lines instead. */
+.canvas-probe .live-offside {
+  position: static;
+  max-width: 100%;
+  overflow: visible;
+  flex-wrap: wrap;
+  row-gap: 5px;
+}
+
+.canvas-probe .sample-groups,
+.canvas-probe .sample-group {
+  flex-wrap: wrap;
+  row-gap: 5px;
+}
+
+/* the selected sample in a well: the editor's rule keys on the
+   probe's `.indicated` class, which wells never carry, so selection
+   read as a hairline at best. Inset outlines so the well's box does
+   not clip them. */
+.canvas-probe .live-offside .sample:has(.value.focus) .value {
+  outline: 2px solid var(--G0);
+  outline-offset: -2px;
+}
+.canvas-probe .live-offside:focus .sample:has(.value.focus) .value {
+  outline: 2px solid var(--R1);
+  outline-offset: -2px;
+  box-shadow: 0 0 0 3px oklch(from var(--R1) l c h / 0.18);
+}
+
+/* rich content participates in the well's flow: the editor's projector
+   base is position:absolute, which left wells 0-height and let cards
+   overlap the strip row below */
+.canvas-probe .value-rich .projector {
+  position: static;
+  display: inline-block;
+}
+
+.focus-slot {
+  width: 100%;
+}
+
+/* ---- type focus: observed inhabitant values ---- */
+
+.type-values {
+  display: flex;
+  flex-wrap: wrap;
+  align-items: center;
+  gap: 6px;
+  margin-top: 6px;
+}
+
+.type-value {
+  border: 1px solid var(--CREASE, #bbb);
+  border-radius: 5px;
+  padding: 2px 8px;
+  font-size: 11px;
+  background: rgba(120, 160, 90, 0.08);
+  white-space: nowrap;
+}
+
+.type-value-count {
+  opacity: 0.55;
+  font-size: 10px;
+}
+
+.type-values-empty {
+  margin-top: 6px;
+  font-size: 11px;
+  opacity: 0.55;
+}
+
+.focus-probe-btn {
+  font-size: 10px;
+  border: 1px solid #4a7a4a;
+  color: #3a6a3a;
+  border-radius: 8px;
+  padding: 1px 8px;
+  cursor: pointer;
+  margin-left: 8px;
+}
+
+.focus-probe-btn:hover {
+  background: rgba(120, 160, 90, 0.15);
+}
+
+.focus-ask-btn {
+  border-color: #2a2a2a;
+  color: #2a2a2a;
+  background: #ffd75e33;
+}
+
+.focus-ask-btn:hover {
+  background: #ffd75e66;
+}
+
+.focus-fn {
+  display: flex;
+  align-items: center;
+  gap: 4px;
+}
+
+.focus-fn.edge-hole .focus-fnbox {
+  border-style: dotted;
+  opacity: 0.6;
+}
+
+.focus-fnbox {
+  border: 2px solid var(--BLACK, #333);
+  border-radius: 7px;
+  padding: 3px 12px;
+  font-size: 12px;
+  font-weight: bold;
+  background: var(--df-bg, #fdfdf4);
+  cursor: pointer;
+}
+
+.focus-fnbox:hover {
+  box-shadow: 0 0 0 2px rgba(120, 160, 90, 0.35);
+}
+
+.focus-arrow {
+  font-size: 15px;
+  opacity: 0.6;
+}
+
+/* ---- legend ---- */
+
+.canvas-legend {
+  flex: 0 0 auto;
+  display: flex;
+  flex-wrap: wrap;
+  gap: 2px 14px;
+  padding: 4px 10px;
+  border-top: 0.6px solid var(--BR2, #ccc);
+  font-size: 10px;
+  opacity: 0.75;
+}
+
+.legend-item {
+  display: flex;
+  align-items: center;
+  gap: 4px;
+  white-space: nowrap;
+}
+
+.legend-glyph {
+  font-weight: bold;
+}
+
+.legend-item.lg-form .legend-glyph,
+.legend-item.lg-hole .legend-glyph {
+  opacity: 0.65;
+}
+
+.legend-item.lg-tests .legend-glyph,
+.legend-pip {
+  color: #4a9a4a;
+  fill: #4a9a4a;
+}
+
+.legend-item.lg-agent .legend-glyph {
+  background: #2a2a2a;
+  color: #ffd75e;
+  border-radius: 3px;
+  padding: 0 3px;
+}
+/* swatches are tiny canvases drawn with the real classes, so the legend
+   cannot drift from what the board draws */
+.legend-swatch {
+  width: 30px;
+  height: 12px;
+  overflow: visible;
+  vertical-align: middle;
+}
+.legend-swatch .canvas-line {
+  stroke-width: 1.4;
+}
+.legend-item.lg-agent .rig-mirror {
+  width: 20px;
+  height: 20px;
+  vertical-align: middle;
+  overflow: visible;
+}
+
+/* ---- the agent avatar ---- */
+
+/* the anchor: positioned by the view; its style attribute is rewritten on
+   every render, so nothing else may live on it */
+.canvas-avatar {
+  position: absolute;
+  z-index: 5;
+  pointer-events: none;
+}
+
+/* the body: the look, the state animations, and the driver's transform;
+   it can be picked up (the anchor itself lets events through) */
+.canvas-avatar .avatar-body {
+  pointer-events: auto;
+  cursor: grab;
+  position: relative; /* the bubbles hang off the body */
+  display: inline-block;
+  font-size: 15px;
+  font-weight: bold;
+  padding: 0 3px;
+  border-radius: 4px;
+  background: #2a2a2a;
+  color: #ffd75e;
+  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.4);
+  will-change: transform;
+}
+
+.canvas-avatar.avatar-err .avatar-body {
+  background: #7a2020;
+  color: #fff;
+  animation: canvas-avatar-shake 0.4s;
+}
+
+.canvas-avatar.avatar-edit .avatar-body {
+  animation: canvas-avatar-bob 1.2s ease-in-out infinite;
+}
+
+/* thinking: no edit landed yet — soft pulse instead of the work bob */
+.canvas-avatar.avatar-think .avatar-body {
+  animation: canvas-avatar-pulse 1.6s ease-in-out infinite;
+  opacity: 0.85;
+}
+
+@keyframes canvas-avatar-pulse {
+  0%,
+  100% {
+    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.4);
+  }
+  50% {
+    box-shadow:
+      0 1px 4px rgba(0, 0, 0, 0.4),
+      0 0 10px 3px rgba(255, 215, 94, 0.55);
+  }
+}
+
+/* streaming chain-of-thought tail beside the avatar */
+/* comic thought bubble: cream cloud + two trailing puffs toward the
+   avatar (down-left). The text is a right-anchored ticker: the newest
+   streamed characters pin to the right edge and push older text left,
+   so marquee motion is paced by the model's actual thinking speed —
+   flavor, not reading material. */
+/* ONE bubble, two skins; CanvasBubble sets mode-speech / mode-thought /
+   mode-hidden and writes left/top every frame */
+.canvas-avatar-bubble {
+  position: absolute;
+  z-index: 6;
+  pointer-events: none;
+  font-weight: normal;
+  font-style: normal;
+  opacity: 0;
+  transition: opacity 140ms;
+}
+.canvas-avatar-bubble.mode-speech,
+.canvas-avatar-bubble.mode-thought {
+  opacity: 1;
+}
+.canvas-avatar-bubble.mode-thought .say-shape,
+.canvas-avatar-bubble.mode-thought .say-text,
+.canvas-avatar-bubble.mode-hidden .say-shape,
+.canvas-avatar-bubble.mode-hidden .say-text,
+.canvas-avatar-bubble.mode-speech .bubble-cloud,
+.canvas-avatar-bubble.mode-hidden .bubble-cloud {
+  display: none;
+}
+/* speech skin: one svg outline (box + tail) under the text */
+.canvas-avatar-bubble .say-shape {
+  position: absolute;
+  left: 0;
+  top: 0;
+  width: 100%;
+  height: 100%;
+  overflow: visible;
+}
+.canvas-avatar-bubble .say-shape path {
+  fill: #f8dc7a;
+  stroke: #3a2a12;
+  stroke-width: 1.3;
+  stroke-linejoin: round;
+}
+.canvas-avatar-bubble .say-text {
+  position: relative;
+  padding: 3px 9px;
+  color: #3a2a12;
+  font-family: var(--code-font, monospace);
+  font-size: 9px;
+  white-space: nowrap;
+}
+
+/* the cloud: an svg outline stretched over the box, text windowed by
+   CanvasBubble on a quick cadence (3 lines of ~28 chars) */
+.bubble-cloud {
+  position: relative;
+  width: 170px;
+  height: 64px;
+  color: #3a2a12;
+  font-size: 9px;
+  line-height: 1.3;
+  font-style: italic;
+}
+.bubble-cloud .bubble-shape {
+  position: absolute;
+  inset: 0;
+  width: 100%;
+  height: 100%;
+  overflow: visible;
+}
+.bubble-cloud .bubble-shape path {
+  fill: #f8dc7a;
+  stroke: #3a2a12;
+  stroke-width: 1.3;
+  vector-effect: non-scaling-stroke;
+  filter: drop-shadow(0 1px 1px rgba(90, 70, 30, 0.2));
+}
+.bubble-cloud .bubble-text {
+  position: absolute;
+  left: 28px;
+  right: 36px;
+  top: 15px;
+  height: 34px; /* exactly three lines: 9px × 1.25 × 3 */
+  line-height: 1.25;
+  overflow: hidden;
+  word-break: break-all;
+}
+/* each replacement fades in; no motion (a lift read as bouncing) */
+.bubble-cloud .bubble-text.flip {
+  animation: bubble-flip 0.24s ease-out;
+}
+@keyframes bubble-flip {
+  from {
+    opacity: 0.45;
+  }
+  to {
+    opacity: 1;
+  }
+}
+/* the tails layer: the speech tail and the cloud's puffs, body-local */
+.canvas-avatar .avatar-body > .bubble-tails {
+  position: absolute;
+  left: -300px;
+  top: -300px;
+  width: 600px;
+  height: 600px;
+  overflow: visible;
+  pointer-events: none;
+  z-index: 7;
+}
+/* puffs are paler than the rig's dots so they read as the cloud's
+   trail, not as extra vertices */
+.bubble-tails .cloud-puff {
+  fill: #fbeeb8;
+  stroke: #7a5a22;
+  stroke-width: 1;
+}
+
+/* the speech bubble: the landed action, at the thought bubble's anchor */
+/* the rig body has no box of its own: offsets clear its vertices */
+/* while speaking, the thought cloud yields the anchor */
+/* the speech bubble is about the landed act: it hides while the body
+   travels; the thought cloud rides along (it is a child of the body) */
+/* the speech skin is about the landed act: it hides while the body
+   travels; the thought skin rides along */
+.avatar-body.mood-travel > .canvas-avatar-bubble.mode-speech,
+.avatar-body.mood-arrive > .canvas-avatar-bubble.mode-speech {
+  opacity: 0 !important;
+}
+
+
+
+
+/* the action toast: dark chip in the avatar's palette, briefly
+   displacing the thought bubble when a tool call's beat lands */
+.canvas-avatar-toast {
+  position: absolute;
+  z-index: 6;
+  pointer-events: none;
+  background: #2a2a2a;
+  color: #ffd75e;
+  font-family: var(--code-font, monospace);
+  font-size: 9px;
+  padding: 3px 7px;
+  border-radius: 5px;
+  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.35);
+  white-space: nowrap;
+  animation: toast-pop 0.18s ease-out;
+}
+
+@keyframes toast-pop {
+  from {
+    opacity: 0;
+    scale: 0.7;
+  }
+  to {
+    opacity: 1;
+    scale: 1;
+  }
+}
+
+.canvas-avatar-toast.b-left {
+  transform: translateX(-100%);
+}
+
+/* orientation flips: near the right edge the bubble sits LEFT of the
+   icon (trail on its right); near the top it sits BELOW (trail on top) */
+
+
+
+
+
+@keyframes bubble-in {
+  from {
+    opacity: 0;
+    translate: 0 4px;
+  }
+  to {
+    opacity: 1;
+    translate: 0 0;
+  }
+}
+
+@keyframes canvas-avatar-bob {
+  0%,
+  100% {
+    margin-top: 0;
+  }
+  50% {
+    margin-top: -4px;
+  }
+}
+
+@keyframes canvas-avatar-shake {
+  0%,
+  100% {
+    margin-left: 0;
