+open Alcotest;
+open Haz3lcore;
+open Language;
+
+/* Alias-body formers fold into the alias node: `type Pos = (Int, Int)`
+ * is ONE node wearing a "()" badge with two component terminals feeding
+ * it — no separate "()@Pos" former. Anonymous formers (a tuple written
+ * inline in a signature) keep their own Product node. */
+
+let prog = {|type Pos = (Int, Int) in
+type Deck = [Pos] in
+type Msg = Inc + Move(Pos) in
+let step : (Pos, Msg) -> Pos =
+fun (p, m) -> p in
+step((1, 2), Inc)|};
+
+let graph_of = (code: string): Web.CanvasGraph.t =>
+  switch (Parser.to_zipper(~root=Exp, code)) {
+  | None => fail("failed to parse program")
+  | Some(z) =>
+    let MakeTerm.{term, _} = MakeTerm.from_zip_for_sem(z, ~root=Exp);
+    let statics =
+      CachedStatics.init_from_term(
+        ~settings=CoreSettings.on,
+        ~is_dynamic_term=false,
+        term,
+      );
+    Web.CanvasGraph.extract(statics);
+  };
+
+let node = (g: Web.CanvasGraph.t, key: string): Web.CanvasGraph.tynode =>
+  switch (
+    List.find_opt((n: Web.CanvasGraph.tynode) => n.key == key, g.nodes)
+  ) {
+  | Some(n) => n
+  | None => fail("no node " ++ key)
+  };
+let has = (g: Web.CanvasGraph.t, key: string): bool =>
+  List.exists((n: Web.CanvasGraph.tynode) => n.key == key, g.nodes);
+
+let tests = [
+  test_case(
+    "product alias wears the () badge and owns its parts",
+    `Quick,
+    () => {
+      let g = graph_of(prog);
+      let pos = node(g, "Pos");
+      check(option(string), "former", Some("()"), pos.former);
+      check(int, "two component terminals", 2, List.length(pos.parts));
+      check(bool, "no separate former node", false, has(g, "()@Pos"));
+      /* the terminals dock at the alias itself */
+      List.iter(
+        pk =>
+          check(
+            option(string),
+            "part " ++ pk ++ " anchored at Pos",
+            Some("Pos"),
+            node(g, pk).sat |> Option.map(fst),
+          ),
+        pos.parts,
+      );
+    },
+  ),
+  test_case(
+    "list alias wears the [] badge",
+    `Quick,
+    () => {
+      let g = graph_of(prog);
+      let deck = node(g, "Deck");
+      check(option(string), "former", Some("[]"), deck.former);
+      check(list(string), "element feeds it", ["Pos"], deck.parts);
+      check(bool, "no separate former node", false, has(g, "[]@Deck"));
+    },
+  ),
+  test_case(
+    "sum alias wears the + badge with no parts",
+    `Quick,
+    () => {
+      let g = graph_of(prog);
+      let msg = node(g, "Msg");
+      check(option(string), "former", Some("+"), msg.former);
+      check(int, "no parts", 0, List.length(msg.parts));
+    },
+  ),
+  test_case(
+    "anonymous input tuples keep their product node",
+    `Quick,
+    () => {
+      let g = graph_of(prog);
+      check(
+        bool,
+        "a Product node exists for step's (Pos, Msg) input",
+        true,
+        List.exists(
+          (n: Web.CanvasGraph.tynode) =>
+            n.kind == Web.CanvasGraph.Product && n.former == None,
+          g.nodes,
+        ),
+      );
+    },
+  ),
+  test_case(
+    "a repeated alias name gets a distinct node key",
+    `Quick,
+    () => {
+      let g = graph_of("type Pos = Int in type Pos = Bool in 1");
+      let keys =
+        List.filter(
+          k => String.length(k) >= 3 && String.sub(k, 0, 3) == "Pos",
+          List.map((n: Web.CanvasGraph.tynode) => n.key, g.nodes),
+        );
+      check(list(string), "keys", ["Pos", "Pos#2"], keys);
+    },
+  ),
+];

@@ -0,0 +1,408 @@
+open Alcotest;
+module S = Web.CanvasScore;
+
+/* The staging language's invariants: one score per beat, the actor
+   precedes every effect, times never run backwards, terminals bloom with
+   their type, pills follow their arrow, a tidy drift comes last. */
+
+let p = (x, y): S.pos => {
+  x,
+  y,
+};
+let node = (~anchor=?, ~order=max_int, key, x, y): S.new_node => {
+  key,
+  anchor,
+  p: p(x, y),
+  order,
+};
+
+let diff =
+    (
+      ~cause="test",
+      ~added=[],
+      ~edges=[],
+      ~removed=[],
+      ~removed_edges=[],
+      ~moved=[],
+      (),
+    ) => {
+  S.d_cause: cause,
+  added,
+  edges,
+  removed,
+  removed_edges,
+  changed: [],
+  moved,
+  actor: Some(p(0., 0.)),
+};
+
+let pos_of_added = (d: S.diff, k) =>
+  List.find_opt((n: S.new_node) => n.key == k, d.added)
+  |> Option.map((n: S.new_node) => n.p);
+
+let appear = (s: S.score, k) => List.assoc(k, S.appear_times(s));
+
+let no_violations = (name, s: S.score) =>
+  check(list(string), name ++ ": validate", [], S.validate(s));
+
+let three_types = () => {
+  /* the bug case of round 100: terminals listed BEFORE their types */
+  let d =
+    diff(
+      ~added=[
+        node(~anchor="Score", "Int@Scorec0", 80., 40.),
+        node(~anchor="Score", "Int@Scorec1", 80., 90.),
+        node("Score", 160., 60.),
+        node("Grade", 160., 240.),
+        node("Name", 160., 420.),
+      ],
+      (),
+    );
+  let s = S.plan(~pos_of=pos_of_added(d), d);
+  check(int, "one act per type", 3, List.length(s.acts));
+  no_violations("three types", s);
+  let a_score = appear(s, "Score")
+  and a_t0 = appear(s, "Int@Scorec0")
+  and a_t1 = appear(s, "Int@Scorec1")
+  and a_grade = appear(s, "Grade")
+  and a_name = appear(s, "Name");
+  check(
+    bool,
+    "type before its terminals",
+    true,
+    a_score < a_t0 && a_t0 < a_t1,
+  );
+  check(bool, "terminals bloom with their type", true, a_t1 - a_score < 400);
+  check(bool, "next type after the first act", true, a_grade > a_t1 + 200);
+  check(bool, "reading order", true, a_score < a_grade && a_grade < a_name);
+  /* the actor's path never runs backwards in time */
+  let path = S.actor_path(~pos_of=pos_of_added(d), s);
+  let ts = List.map(((t, _, _)) => t, path);
+  check(list(int), "actor path sorted", List.sort(compare, ts), ts);
+  check(
+    bool,
+    "about a second per type",
+    true,
+    s.total_ms > 4500 && s.total_ms < 9000,
+  );
+};
+
+let actor_first = () => {
+  let d = diff(~added=[node("A", 100., 100.)], ());
+  let s = S.plan(~pos_of=pos_of_added(d), d);
+  let (t0, a) = List.hd(s.acts);
+  check(int, "first act at 0", 0, t0);
+  List.iter(
+    (e: S.timed_effect) =>
+      check(
+        bool,
+        "effect after arrival+pause",
+        true,
+        e.at >= a.travel_ms + a.pause_ms,
+      ),
+    a.effects,
+  );
+};
+
+let edge_after_types = () => {
+  /* Grade already exists; the arrow lands on a NEW terminal of it */
+  let d =
+    diff(
+      ~added=[
+        node("Score", 100., 100.),
+        node(~anchor="Grade", "Grade@quiz", 440., 100.),
+      ],
+      ~edges=[
+        {
+          S.name: "quiz",
+          src: "Score",
+          dst: "Grade@quiz",
+          product: None,
+        },
+      ],
+      (),
+    );
+  let pos_of = k => k == "Grade" ? Some(p(400., 100.)) : pos_of_added(d, k);
+  let s = S.plan(~pos_of, d);
+  no_violations("edge after types", s);
+  let effs = S.effects_abs(s);
+  let t_of = f =>
+    List.find_map(
+      ((t, _, e: S.timed_effect)) => f(e.effect) ? Some(t) : None,
+      effs,
+    )
+    |> Option.get;
+  let t_draw = t_of(e => e == S.Draw("quiz"))
+  and t_pill = t_of(e => e == S.Pill("quiz"))
+  and t_score = t_of(e => e == S.Appear("Score"))
+  and t_term = t_of(e => e == S.Appear("Grade@quiz"));
+  check(bool, "types before the arrow", true, t_score < t_draw);
+  check(
+    bool,
+    "arrow's terminal blooms as it lands",
+    true,
+    t_term > t_draw && t_term <= t_pill,
+  );
+  check(bool, "pill after the arrow", true, t_pill > t_draw);
+  let (_, last) = List.nth(s.acts, List.length(s.acts) - 1);
+  check(bool, "edge act is last", true, last.at == S.Edge("quiz"));
+};
+
+/* A2 without exception (2026-09-06): many definitions are many acts, each
+   at its own site; a long beat compresses its tempo instead of merging */
+let no_batch = () => {
+  let d =
+    diff(
+      ~added=
+        List.init(14, i =>
+          node("T" ++ string_of_int(i), float_of_int(i) *. 50., 0.)
+        ),
+      (),
+    );
+  let s = S.plan(~pos_of=pos_of_added(d), d);
+  check(int, "one act per definition", 14, List.length(s.acts));
+  List.iter(
+    ((_, a): (int, S.act)) =>
+      switch (a.at) {
+      | S.Centroid(_) => fail("a centroid act (batch) in a scored beat")
+      | _ => ()
+      },
+    s.acts,
+  );
+  no_violations("no batch", s);
+  check(list(string), "coverage", [], S.coverage(d, s));
+  check(int, "all appear", 14, List.length(S.appear_times(s)));
+  check(bool, "within budget", true, s.total_ms <= S.tempo.budget_ms);
+};
+
+/* many edges: every one ridden by its own act, none left to a "rest" act */
+let every_edge_ridden = () => {
+  let types = ["A", "B", "C", "D"];
+  let d =
+    diff(
+      ~added=
+        List.mapi((i, k) => node(k, float_of_int(i) *. 120., 40.), types),
+      ~edges=
+        List.init(8, i =>
+          {
+            S.name: "f" ++ string_of_int(i),
+            src: List.nth(types, i mod 4),
+            dst: List.nth(types, (i + 1) mod 4),
+            product: None,
+          }
+        ),
+      (),
+    );
+  let s = S.plan(~pos_of=pos_of_added(d), d);
+  let edge_acts =
+    List.filter(
+      ((_, a): (int, S.act)) =>
+        switch (a.at) {
+        | S.Edge(_) => true
+        | _ => false
+        },
+      s.acts,
+    );
+  check(int, "one act per edge", 8, List.length(edge_acts));
+  check(list(string), "coverage", [], S.coverage(d, s));
+  no_violations("every edge ridden", s);
+};
+
+/* the coverage check names what the score forgot */
+let coverage_catches = () => {
+  let d = diff(~added=[node("A", 0., 0.), node("B", 100., 0.)], ());
+  let s = S.plan(~pos_of=pos_of_added(d), d);
+  let d' =
+    diff(
+      ~added=[node("A", 0., 0.), node("B", 100., 0.), node("Z", 200., 0.)],
+      (),
+    );
+  check(
+    list(string),
+    "unstaged node named",
+    ["ORPHAN: node Z unstaged"],
+    S.coverage(d', s),
+  );
+};
+
+let drift_last = () => {
+  let d =
+    diff(
+      ~added=[node("A", 100., 100.)],
+      ~moved=[
+        ("B", p(300., 100.), p(400., 140.)),
+        ("C", p(300., 200.), p(400., 260.)),
+      ],
+      (),
+    );
+  let pos_of = k =>
+    switch (k) {
+    | "B" => Some(p(400., 140.))
+    | "C" => Some(p(400., 260.))
+    | k => pos_of_added(d, k)
+    };
+  let s = S.plan(~pos_of, d);
+  no_violations("drift", s);
+  /* existing nodes make room before the arrival */
+  let (_, first) = List.hd(s.acts);
+  check(bool, "tidy act first", true, first.emote == S.Tidy);
+  switch (S.drift_at(s)) {
+  | Some(t) =>
+    check(bool, "drift before the arrival", true, t < appear(s, "A"))
+  | None => fail("no drift")
+  };
+};
+
+let framing = () => {
+  let pane = (800., 600.);
+  let cur: S.frame = {
+    center: p(400., 300.),
+    zoom: 1.,
+  };
+  let all = [p(300., 300.), p(500., 300.), p(400., 200.)];
+  /* everything already in view: hold still */
+  check(
+    bool,
+    "hold when all visible",
+    true,
+    S.frame_for(~pane, ~cur, ~all, ~required=[p(500., 300.)], ()) == None,
+  );
+  /* the whole program fits but sits off-center: frame it */
+  let far_cur: S.frame = {
+    center: p(1400., 300.),
+    zoom: 1.,
+  };
+  switch (
+    S.frame_for(~pane, ~cur=far_cur, ~all, ~required=[p(500., 300.)], ())
+  ) {
+  | Some(f) =>
+    check(
+      bool,
+      "frames the whole program",
+      true,
+      abs_float(f.center.x -. 400.) < 1.,
+    );
+    check(bool, "never zooms in", true, f.zoom <= 1.);
+  | None => fail("expected a frame")
+  };
+  /* a large program: required point off to the right -> minimal pan, same zoom */
+  let big =
+    List.init(40, i =>
+      p(float_of_int(i) *. 100., float_of_int(i mod 7) *. 150.)
+    );
+  switch (
+    S.frame_for(~pane, ~cur, ~all=big, ~required=[p(1000., 300.)], ())
+  ) {
+  | Some(f) =>
+    check(
+      bool,
+      "pans right just enough",
+      true,
+      f.center.x > 400. && f.center.x < 1000.,
+    );
+    check(bool, "keeps zoom", true, abs_float(f.zoom -. 1.) < 0.001);
+    check(
+      bool,
+      "no vertical fidget",
+      true,
+      abs_float(f.center.y -. 300.) < 1.,
+    );
+  | None => fail("expected a pan")
+  };
+};
+
+/* removals are acts: the arrow first, at its label, then the node */
+let removals_choreographed = () => {
+  let d =
+    diff(
+      ~removed=[("Old", p(300., 100.))],
+      ~removed_edges=[("f", p(200., 120.))],
+      (),
+    );
+  let s = S.plan(~pos_of=_ => None, d);
+  check(int, "two acts", 2, List.length(s.acts));
+  check(
+    bool,
+    "erase emote",
+    true,
+    List.for_all(
+      ((_, a): (int, S.act)) =>
+        switch (a.emote) {
+        | S.Erase => true
+        | _ => false
+        },
+      s.acts,
+    ),
+  );
+  check(list(string), "coverage", [], S.coverage(d, s));
+  no_violations("removals", s);
+  switch (s.acts) {
+  | [(_, first), ..._] =>
+    check(
+      bool,
+      "the arrow goes before the node",
+      true,
+      List.exists(
+        (e: S.timed_effect) =>
+          switch (e.effect) {
+          | S.Erase("f") => true
+          | _ => false
+          },
+        first.effects,
+      ),
+    )
+  | [] => fail("no acts")
+  };
+};
+
+/* a modification is an act too: the actor touches the element, the look
+   swaps at the cue (the view stages the old look until then) */
+let changes_choreographed = () => {
+  let d = {
+    ...diff(~added=[node("New", 300., 100.)], ()),
+    changed: [("f", p(120., 80.)), ("Kind", p(40., 40.))],
+  };
+  let s = S.plan(~pos_of=_ => None, d);
+  check(int, "three acts", 3, List.length(s.acts));
+  check(list(string), "coverage", [], S.coverage(d, s));
+  no_violations("changes", s);
+  let cues = S.change_times(s);
+  check(
+    bool,
+    "both cued",
+    true,
+    List.mem_assoc("f", cues) && List.mem_assoc("Kind", cues),
+  );
+  /* changes come before additions */
+  let t_new = appear(s, "New");
+  check(
+    bool,
+    "changes precede the addition",
+    true,
+    List.for_all(((_, t)) => t < t_new, cues),
+  );
+};
+
+let tests = [
+  test_case(
+    "three types, terminals with their type, path monotonic",
+    `Quick,
+    three_types,
+  ),
+  test_case("the actor precedes every effect", `Quick, actor_first),
+  test_case("edges after types, pill after arrow", `Quick, edge_after_types),
+  test_case(
+    "many definitions: one act each, no centroid batch",
+    `Quick,
+    no_batch,
+  ),
+  test_case("many edges: every one ridden", `Quick, every_edge_ridden),
+  test_case("coverage names unstaged elements", `Quick, coverage_catches),
+  test_case(
+    "removals: arrow then node, erase acts",
+    `Quick,
+    removals_choreographed,
+  ),
+  test_case("a drift makes room before arrivals", `Quick, drift_last),
+  test_case("framing: hold, frame whole, minimal pan", `Quick, framing),
+];

